#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# Run from the repository root: deploy/ci-runner/wizard.sh. Only the VM's
# address is saved, outside the repository. The runner token is never saved:
# it goes straight to the VM over SSH.
ENV_FILE="${HOME}/.config/wayscribe/ci-runner.env"
mkdir -p "$(dirname "$ENV_FILE")"
SETUP="deploy/ci-runner/setup.sh"
[[ -f "$SETUP" ]] || { echo "run this from the wayscribe repository root" >&2; exit 1; }
KEY="${HOME}/.ssh/wayscribe_runner_admin"
HOST_ALIAS="wayscribe-runner"
PROJECT="jojithedev/wayscribe"
PROJECT_ENCODED="${PROJECT//\//%2F}"

banner "Wayscribe self-hosted GitLab runner"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "SSH key for the runner VM"
if [[ -f "$KEY" ]]; then
  say "Found ${KEY}, reusing it."
else
  say "Creating an ed25519 key for root on the runner VM."
  note "ssh-keygen asks for a passphrase; your choice, the wizard copes either way."
  ssh-keygen -t ed25519 -f "$KEY" -C "wayscribe-runner-admin"
fi
if command -v pbcopy >/dev/null 2>&1; then
  pbcopy < "${KEY}.pub"
  say "The public key is on your clipboard:"
else
  say "Copy this public key:"
fi
note "$(cat "${KEY}.pub")"
pause "Press Enter when you have it"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Create the VM in Hetzner"
open_url "https://console.hetzner.cloud/"
step "Open the project the demo VM lives in, then Add Server."
step "Location: any; the same as the demo is fine."
step "Image: Ubuntu 24.04."
step "Type: Shared vCPU, x86 (not Arm), 4 vCPU / 8 GB RAM / 80 GB disk or more."
step "Networking: public IPv4 on. IPv6 optional."
step "SSH keys: Add SSH key, paste the key from stage 1, name it wayscribe-runner-admin."
step "Name: wayscribe-runner-1. Create & Buy now."
step "Copy the server's IPv4 address once it shows."
while :; do
  ask RUNNER_IP "Paste the IPv4 address:"
  [[ "$RUNNER_IP" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ ]] && break
  warn "that is not an IPv4 address"
done
write_env RUNNER_IP "$RUNNER_IP"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Firewall: SSH in, nothing else"
say "The runner only connects out to gitlab.com, so only SSH comes in."
open_url "https://console.hetzner.cloud/"
step "In the same project: Firewalls, then Create Firewall."
step "Inbound rules: keep only TCP port 22 (any IPv4, any IPv6). ICMP may stay."
step "Outbound rules: leave empty (all outbound allowed)."
step "Apply to: wayscribe-runner-1. Name it wayscribe-runner. Create Firewall."
note "The VM's own ufw also denies everything but 22; this is the second layer."
pause "Press Enter when the firewall is applied"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "SSH alias and first login"
mkdir -p "${HOME}/.ssh"
if grep -qE "^Host ${HOST_ALIAS}\$" "${HOME}/.ssh/config" 2>/dev/null; then
  if ! grep -A3 -E "^Host ${HOST_ALIAS}\$" "${HOME}/.ssh/config" | grep -q "HostName ${RUNNER_IP}\$"; then
    warn "~/.ssh/config already has Host ${HOST_ALIAS} with a different address."
    say "Edit it to HostName ${RUNNER_IP}, then continue."
    pause "Press Enter when it is fixed"
  else
    say "~/.ssh/config already has Host ${HOST_ALIAS} → ${RUNNER_IP}."
  fi
else
  printf '\nHost %s\n  HostName %s\n  User root\n  IdentityFile %s\n  IdentitiesOnly yes\n' \
    "$HOST_ALIAS" "$RUNNER_IP" "$KEY" >> "${HOME}/.ssh/config"
  printf '  %s✓ added%s Host %s to ~/.ssh/config\n' "$GREEN" "$RESET" "$HOST_ALIAS"
fi
say "Connecting. The first connection records the VM's host key (trust on first use)."
until ssh -o ConnectTimeout=10 -o StrictHostKeyChecking=accept-new "$HOST_ALIAS" true; do
  warn "not reachable yet; the VM may still be booting."
  confirm "Try again?" || exit 1
done
printf '  %s✓%s logged in as root on %s\n' "$GREEN" "$RESET" "$RUNNER_IP"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Set up the host"
say "Runs ${SETUP} on the VM: Docker, GitLab Runner, arm64 emulation,"
say "SSH keys only, ufw (22 only), security updates, a daily Docker prune."
note "About three minutes. Safe to rerun."
confirm "Run the setup on ${RUNNER_IP} now?" || exit 1
scp -q "$SETUP" "${HOST_ALIAS}:/root/wayscribe-runner-setup.sh"
ssh "$HOST_ALIAS" 'sh /root/wayscribe-runner-setup.sh'
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Create the runner in GitLab and register it"
open_url "https://gitlab.com/${PROJECT}/-/settings/ci_cd#js-runners-settings"
step "Runners, expand, then New project runner."
step "Platform: Linux."
step "Tags: self-hosted"
step "Leave 'Run untagged jobs' UNCHECKED."
step "Description: wayscribe-runner-1"
step "Leave 'Protected' UNCHECKED: branch and merge request pipelines run here;"
note "    release jobs are kept on GitLab's runners by the CI configuration instead."
step "Create runner, then copy the token (starts glrt-). Ignore the register command shown."
note "The token is sent to the VM over SSH and not saved anywhere on this machine."
while :; do
  ask_secret RUNNER_TOKEN "Paste the runner token:"
  [[ "$RUNNER_TOKEN" == glrt-* ]] && break
  warn "that does not start with glrt-"
done
printf '%s\n' "$RUNNER_TOKEN" | ssh "$HOST_ALIAS" 'sh /root/wayscribe-runner-setup.sh register'
unset RUNNER_TOKEN
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Check GitLab sees it"
if command -v glab >/dev/null 2>&1; then
  for _ in 1 2 3 4 5 6; do
    status=$(glab api "projects/${PROJECT_ENCODED}/runners?type=project_type" 2>/dev/null |
      python3 -c 'import json,sys
for r in json.load(sys.stdin):
    if r.get("description","").startswith("wayscribe-runner"): print(r["status"]); break' || true)
    [[ "$status" == online ]] && break
    sleep 10
  done
  if [[ "$status" == online ]]; then
    printf '  %s✓%s the runner is online in %s\n' "$GREEN" "$RESET" "$PROJECT"
  else
    warn "GitLab reports the runner as '${status:-missing}'."
    SKIPPED+=("confirm the runner is online: Settings → CI/CD → Runners")
  fi
else
  open_url "https://gitlab.com/${PROJECT}/-/settings/ci_cd#js-runners-settings"
  step "Under Runners, wayscribe-runner-1 should show a green 'online' dot."
  pause
fi
say "Jobs go to it once the project variable RUNNER_TAG is self-hosted (docs/CI_RUNNER.md)."
say "Credential-holding release jobs stay on GitLab's runners either way."
if [[ "${status:-}" == online ]] && command -v glab >/dev/null 2>&1 &&
  confirm "Set RUNNER_TAG=self-hosted on ${PROJECT} now?"; then
  if glab variable set RUNNER_TAG --value self-hosted --repo "$PROJECT" >/dev/null 2>&1 ||
    glab variable update RUNNER_TAG --value self-hosted --repo "$PROJECT" >/dev/null 2>&1; then
    printf '  %s✓ set%s RUNNER_TAG=self-hosted; the next pipeline uses the runner\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("set the project variable RUNNER_TAG=self-hosted (Settings → CI/CD → Variables)")
  fi
else
  SKIPPED+=("set the project variable RUNNER_TAG=self-hosted when you are ready")
fi
note "To fall back to GitLab's runners: glab variable delete RUNNER_TAG --repo ${PROJECT}"
pause

finish
}

run_wizard "$@"; exit
